Translate("ruRU", "varimathras", {
	title = "Вариматас",
	subtitle = "Наместник Темной Госпожи",
	found = "Королевский квартал в Подгороде, рядом с Темной Госпожой",
	hint = [=[Поговорите с повелителем ужаса, который стоит рядом с Королевой-банши.]=],
	allegiance = "Отрекшиеся · прежде Пылающий Легион",
	sections = {
		{
			title = "Обзор",
			text = [=[Вариматас — повелитель ужаса, один из натрезимов {link:burning-legion}Пылающего Легиона{/link}. После того как пал {link:archimonde}Архимонд{/link}, он и его сородичи попытались захватить разоренное королевство {link:lordaeron}Лордерон{/link} для себя. {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link} взяла его в плен и предложила выбор: служить ей или умереть. Он выбрал службу. Он помог ей низвергнуть его собственных собратьев и с тех пор стоит рядом с ней, в самом глубоком зале ее города.]=],
		},
		{
			title = "Значение",
			text = [=[Вариматас — наместник Темной Госпожи и хозяин обороны {link:undercity}Подгород{/link}а. Его лазутчики и солдаты рыщут по всему Тирисфалю, и он занимается ближайшими к дому врагами, пока его королева следит за севером. То, что демон Легиона служит Отрекшимся, — странный факт. Многие {link:forsaken}Отрекшиеся{/link} предпочитают о нем не думать. Те же, кто думает, знают лишь то, что видели: он безупречно служит своей королеве с того дня, как она его пощадила, и презирает человечество не меньше, чем она. Его солдатам говорят, что он сам следит за тем, чтобы род людской был стерт с лица {link:lordaeron}Лордерон{/link}а.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он присягнул королеве и помог ей свергнуть повелителей ужаса, правивших разоренным королевством.
• Он командует обороной {link:undercity}Подгород{/link}а.
• Он руководит войной против {link:scarlet-crusade}Алого ордена{/link} и хочет смерти его вождей.
• Он принимает доклады ловчих смерти, шпионов Темной Госпожи.
• Он охотится на лазутчиков {link:scourge}Плети{/link} далеко за пределами {link:lordaeron}Лордерон{/link}а.
• Он ищет книги заклинаний клана Палящего Клинка, спрятанные в пещерах под {link:orgrimmar}Оргриммар{/link}ом, для нужд Темной Госпожи.]=],
		},
	},
	chapters = {
		{
			title = "Красные муравьи",
			hint = "Нанесите удар в сердце Алого ордена.",
			text = [=[Пока {link:sylvanas-windrunner}Темная Госпожа{/link} занята наступлением Короля-лича на севере, Вариматас ведает делами поближе к дому. Он называет {link:scarlet-crusade}Алый орден{/link} самым острым шипом в боку Отрекшихся и хочет, чтобы верховный инквизитор {link:high-inquisitor-whitemane}Вайтмейн{/link} и ее главные помощники были убиты в залах {link:scarlet-monastery}Монастыря Алого ордена{/link}.]=],
		},
		{
			title = "Ловчие смерти",
			hint = "Раскройте заговоры лордов Альтерака.",
			text = [=[Ловчие смерти узнали, что {link:syndicate}Синдикат{/link} состоит из прежних лордов {link:alterac-mountains}Альтерак{/link}а, предателей {link:second-war}Второй войны{/link}. Их доклад попал к повелителю ужаса. Вариматас доволен такой работой и вознаграждает ее.]=],
		},
		{
			title = "Нечестивый союз",
			hint = "Найдите посла Плети, отправленного к свинобразам.",
			text = [=[Король-лич отправил посла {link:ambassador-malcin}Малсин{/link}а к {link:quilboar}свинобраз{/link}ам Курганов Иглошкурых, и у некоторых свинобразов начали проявляться признаки чумы. Вариматас хотел, чтобы посол был мертв, а его поручение провалено. Когда Малсин пал, повелитель ужаса передал благодарность Темной Госпожи.]=],
		},
	},
	mentions = {
		{ text = "«В {link:scarlet-monastery}Монастырь Алого ордена{/link}»" },
		{ text = "«Стражи смерти»" },
		{ text = "«Нечестивый союз»" },
		{ text = "«Сила разрушения...»" },
		{ text = "«Доказательство гибели»" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "Сильвана Ветрокрылая", note = "его королева" },
		{ id = "garek-bandarion", name = "Гарек Бандарион", note = "по его приказу создал городскую стражу" },
	},
})

Translate("ruRU", "master-apothecary-faranell", {
	title = "Главный аптекарь Фаранелл",
	subtitle = "Хозяин Аптекариума",
	found = "Аптекариум",
	hint = "Отыщите главного аптекаря в подземельях Аптекариума.",
	allegiance = "Королевское фармацевтическое общество",
	aliases = { "Фаранелл" },
	sections = {
		{
			title = "Обзор",
			text = [=[Главный аптекарь Фаранелл правит {link:the-apothecarium}Аптекариум{/link}ом. Он надзирает за самым честолюбивым трудом {link:royal-apothecary-society}Королевского фармацевтического общества{/link} — новой чумой, которую приказала создать {link:sylvanas-windrunner}Темная Госпожа{/link}: болезнью, что принесет гибель {link:scourge}Плети{/link}, а со временем и живым. Его собратья присылают ему свои находки из Серебряного бора, {link:hillsbrad-foothills}Хилсбрад{/link}а и более дальних краев. К своей работе он относится с весельем, которое пугает тех, кто ее понимает.]=],
		},
		{
			title = "Значение",
			text = [=[Фаранелл — место, где сходится воедино знание общества. Он также создает поганищ для Темной Госпожи и не прочь пошутить за счет своих подопытных.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он изучает древнюю чуму, что некогда убила жизнь в Озере Лордамер.
• Он добавляет к варевам своих собратьев собственный коллоид разложения.
• Он подчиняет сшитых мертвецов воле Темной Госпожи.]=],
		},
	},
	chapters = {
		{
			title = "Рецепт смерти",
			hint = "Доставьте находки аптекарей в Подгород.",
			text = [=[Аптекарь Берард изучал древнюю чуму Озера Лордамер, пока проклятие чародея {link:archmage-arugal}Аругал{/link}а не отняло у него разум. Его дневник уцелел. Фаранелл продолжил этот труд и сказал тому, кто принес дневник, что общество стоит на пороге чего-то великого.]=],
		},
		{
			title = "Бесконечная мука",
			hint = "Найдите того, кто знает поганище с чужой головой.",
			text = [=[Одно поганище в руинах наверху теряло голову так много раз, что она едва держалась. Фаранелл узнал ее сразу. Она принадлежала гранд-маршалу {link:alliance}Альянс{/link}а, которого {link:sylvanas-windrunner}Темная Госпожа{/link} убила собственной рукой. Фаранелл велел приладить голову к новому телу, а когда та отказалась служить, напоил ее сывороткой собственного приготовления. На будущее головы, которую звали Отмар, у него много планов.]=],
		},
	},
	mentions = {
		{ text = "«Рецепт смерти»" },
		{ text = "«Рецепт смерти»" },
		{ text = "«Эликсир мучений»" },
		{ text = "«Бесконечные муки»" },
		{ text = "«Бесконечные муки»" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "Сильвана Ветрокрылая", note = "его королева" },
		{ id = "apothecary-keever", name = "Аптекарь Кивер", note = "работает в его подземельях" },
		{ id = "apothecary-johaan", name = "Аптекарь Йохаан", note = "из его общества" },
	},
})

Translate("ruRU", "bethor-iceshard", {
